  static const focusAreas=['NR-12','NR-06','NR-17','NR-18','NR-23','NR-31','NR-35','Outras'];
  static String normalize(String value) {
    var s=value.toLowerCase();
    const accents={'á':'a','à':'a','â':'a','ã':'a','é':'e','ê':'e','í':'i','ó':'o','ô':'o','õ':'o','ú':'u','ç':'c'};
    accents.forEach((a,b)=>s=s.replaceAll(a,b));
    return s.replaceAll(RegExp(r'[^a-z0-9\s]'),' ').replaceAll(RegExp(r'\s+'),' ').trim();
  }

  /// Exige que equipamento/tema E a falha estejam explícitos no relato.
  /// Quando a ocorrência estiver regularizada ou não confirmada, não propõe NC.
  static List<Map<String,String>> matches(String description) {
    final s=normalize(description);
    if (s.length<6 || s.length>3000) return const [];
    if (RegExp(r'\b(nao verificado|nao confirmado|talvez|suspeita|ja corrigido|regularizado|funcionando normalmente|sem irregularidade)\b').hasMatch(s)) return const [];
    if (RegExp(r'\bnao (?:esta |foi |se encontra )?(?:vencido|vencida|quebrado|inoperante|obstruido|bloqueado|danificado)\b').hasMatch(s)) return const [];
    return entries.where((e) =>
      RegExp(e['entityRegex']!).hasMatch(s) &&
      RegExp(e['faultRegex']!).hasMatch(s)
    ).toList(growable:false);
  }
}
